[] a sh:ValidationReport ;
    sh:conforms false ;
    sh:result [ a sh:ValidationResult ;
            sh:focusNode [ a schema1:HowTo ;
                    schema1:step [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalProperty <https://ada.astromat.org/metadata/parameter/module/ICPMS/filteringApproachDefault>,
                                <https://ada.astromat.org/metadata/parameter/module/UPb/intermediateDaughterDisequilibriumCorrection> ;
                            schema1:additionalType <https://bioschemas.org/LabProcess> ;
                            schema1:name "Data processing" ;
                            schema1:position 3 ;
                            ns1:detectionLimitMethod "no value available: ada:detectionLimitMethod" ],
                        [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalType <https://bioschemas.org/LabProcess> ;
                            schema1:description "Thick sections embedded in petropoxy 154 resin, the surface finalised by polishing with 0.5 µm diamond paste; carbon-coated before the EPMA measurements (§2.1–2.2). Whether the coat was removed before ablation is not stated; the later 0.5 µm polish (§2.5) preceded micromilling, not ablation" ;
                            schema1:name "Sample preparation" ;
                            schema1:position 1 ;
                            ns1:chemicalAbrasionConditions "N — the procedure reports no date" ],
                        [ a <http://ddialliance.org/Specification/DDI-CDI/1.0/RDF/Activity>,
                                schema1:Action,
                                schema1:HowToStep ;
                            schema1:additionalType <https://bioschemas.org/LabProcess> ;
                            schema1:description "no value available: schema:description" ;
                            schema1:name "Data acquisition" ;
                            schema1:position 2 ] ] ;
            sh:resultMessage "A HowTo methodology must have a schema:name" ;
            sh:resultPath schema1:name ;
